Definition fs_push (Σ : rtsA) (k : nat) (g : fsst) (f : Z) : rtsA :=
  mkRtsA (lay Σ) (pr Σ) (ca Σ) (ca_init Σ) (sec Σ) (sec_nres Σ) (aw Σ) (ql Σ) (qg Σ) (dep Σ)
    (match k with 0%nat => g | _ => fs0 Σ end) (match k with 1%nat => g | _ => fs2 Σ end)
    (match k with 6%nat => g | _ => fs4 Σ end) (match k with 2%nat => g | _ => fs1 Σ end) (match k with 3%nat => g | _ => fc3 Σ end) (match k with 4%nat => g | _ => fc4 Σ end) (match k with 7%nat => g | _ => fc7 Σ end) (ia_init Σ) (credit Σ - 1) (live Σ) ((f, k) :: frames Σ).

Lemma fs_of_push : forall Σ k g f k', (k = 0 \/ k = 1 \/ k = 6 \/ k = 2 \/ k = 3 \/ k = 4 \/ k = 7)%nat -> (k' = 0 \/ k' = 1 \/ k' = 6 \/ k' = 2 \/ k' = 3 \/ k' = 4 \/ k' = 7)%nat ->
