  ART_A Σ m -> (k = 0 \/ k = 1 \/ k = 6 \/ k = 2 \/ k = 3 \/ k = 4 \/ k = 7)%nat -> 0 <= j < NF (Z.of_nat k) ->
  nth (Z.to_nat ((fss_hint (fs_of Σ k) + j) mod NF (Z.of_nat k))) (fss_flags (fs_of Σ k)) 1 = 0 ->
